const e=i.extmetadata||{};const o={title:p.title,descriptionurl:i.descriptionurl,url:i.url,thumburl:i.thumburl,width:i.width,height:i.height,mime:i.mime};
for(const k of ['LicenseShortName','LicenseUrl','Artist','Credit','UsageTerms','AttributionRequired','DateTimeOriginal','ImageDescription','Copyrighted','Restrictions','License'])o[k]=strip((e[k]||{}).value);
console.log(JSON.stringify(o,null,1));}
EOF
