#!/bin/bash
# usage: fetch.sh shortname "File title without File:" [ext]
S="/c/Users/coneil/AppData/Local/Temp/claude/87995a179e8ca25a/62d1c137-a316-4c55-b30a-3f6dac53053e/scratchpad/research/images-extra"
Q=$(node -e "console.log(encodeURIComponent('File:'+process.argv[1]))" "$2")
